ELEMENTS: dict[int, dict] = {e["Z"]: e for e in _RAW}
_BY_SYMBOL: dict[str, dict] = {e["symbol"].upper(): e for e in _RAW}
_BY_NAME:   dict[str, dict] = {e["name"].lower(): e for e in _RAW}


def get_element(query: int | str) -> dict | None:
    """Look up an element by atomic number, symbol, or name."""
    if isinstance(query, int):
        return ELEMENTS.get(query)
    q = str(query).strip()
    by_sym = _BY_SYMBOL.get(q.upper())
    if by_sym:
        return by_sym
    return _BY_NAME.get(q.lower())
